package kvp

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
	"unicode/utf8"
)

const (
	DefaultDir        = "/var/lib/hyperv"
	WireMaxKeyBytes   = 512
	WireMaxValueBytes = 2048
	SafeMaxKeyBytes   = 254
	SafeMaxValueBytes = 1022
	RecordSize        = WireMaxKeyBytes + WireMaxValueBytes
	MaxUniqueKeys     = 1024
)

// Pool selects a Hyper-V pool file. Auto is normally generated by the daemon;
// AutoInternal is an internal index, not an application telemetry destination.
type Pool uint8

const (
	External Pool = iota
	Guest
	Auto
	AutoExternal
	AutoInternal
)

func (p Pool) String() string {
	switch p {
	case External:
		return "external"
	case Guest:
		return "guest"
	case Auto:
		return "auto"
	case AutoExternal:
		return "auto-external"
	case AutoInternal:
		return "auto-internal"
	default:
		return fmt.Sprintf("Pool(%d)", p)
	}
}

// FileName returns the conventional pool-file name, rejecting invalid indices.
func (p Pool) FileName() (string, error) {
	if p > AutoInternal {
		return "", ErrInvalidPool
	}
	return fmt.Sprintf(".kvp_pool_%d", p), nil
}

// PoolMode controls write limits, counted in UTF-8 bytes, not runes. Reading
// never applies write limits. Unsafe records may be truncated in host transport.
type PoolMode uint8

const (
	Safe PoolMode = iota
	Unsafe
)

func (m PoolMode) String() string {
	switch m {
	case Safe:
		return "safe"
	case Unsafe:
		return "unsafe"
	default:
		return fmt.Sprintf("PoolMode(%d)", m)
	}
}

// Record is one physical pool record. Slices of records preserve duplicates.
type Record struct {
	Key   string `json:"key"`
	Value string `json:"value"`
}

// Store selects one pool file. It is safe to share a Store between goroutines.
// Each operation opens and locks its own descriptor. Failed I/O may leave
// partial writes; validation failures write nothing.
type Store struct {
	path string
	pool Pool
	mode PoolMode
	ops  storeOps
}

func NewStore(pool Pool, mode PoolMode) (*Store, error) {
	return NewStoreIn(pool, DefaultDir, mode)
}

// NewStoreIn selects a directory without opening or creating any files.
func NewStoreIn(pool Pool, dir string, mode PoolMode) (*Store, error) {
	name, err := pool.FileName()
	if err != nil {
		return nil, err
	}
	if mode != Safe && mode != Unsafe {
		return nil, ErrInvalidMode
	}
	// Preserve ".." and symlink traversal, as Rust's PathBuf::join does.
	if dir != "" && !os.IsPathSeparator(dir[len(dir)-1]) {
		dir += string(os.PathSeparator)
	}
	return &Store{path: dir + name, pool: pool, mode: mode, ops: osStoreOps{}}, nil
}

func (s *Store) Path() string   { return s.path }
func (s *Store) Pool() Pool     { return s.pool }
func (s *Store) Mode() PoolMode { return s.mode }
func (s *Store) MaxKeySize() int {
	if s.mode == Unsafe {
		return WireMaxKeyBytes
	}
	return SafeMaxKeyBytes
}
func (s *Store) MaxValueSize() int {
	if s.mode == Unsafe {
		return WireMaxValueBytes
	}
	return SafeMaxValueBytes
}

// Append preserves existing records and duplicates, without a record-count cap.
func (s *Store) Append(key, value string) error {
	return s.AppendMultiple([]Record{{Key: key, Value: value}})
}

// AppendMultiple validates the whole batch before writing under one lock.
// Empty input is a no-op, even when the pool directory is absent.
func (s *Store) AppendMultiple(records []Record) error {
	if len(records) == 0 {
		return nil
	}
	if err := s.validateRecords(records); err != nil {
		return err
	}
	return s.withFile(os.O_RDWR|os.O_CREATE, true, true, func(f *poolFile) error {
		for _, record := range records {
			if err := f.append(record); err != nil {
				return err
			}
		}
		return nil
	})
}

// Insert replaces the first matching value and removes all its duplicates.
// Removal swaps in the final record and may reorder unrelated records.
func (s *Store) Insert(key, value string) error {
	if err := s.validateRecords([]Record{{Key: key, Value: value}}); err != nil {
		return err
	}
	return s.withFile(os.O_RDWR|os.O_CREATE, true, true, func(f *poolFile) error {
		found := false
		keys := make(map[string]struct{})
		for i := int64(0); i < f.count; {
			record, err := f.read(i)
			if err != nil {
				return err
			}
			keys[record.Key] = struct{}{}
			if record.Key == key {
				if found {
					if err := f.remove(i); err != nil {
						return err
					}
					continue
				}
				var field [WireMaxValueBytes]byte
				copy(field[:], value)
				if err := writeAt(f.file, field[:], i*RecordSize+WireMaxKeyBytes); err != nil {
					return err
				}
				found = true
			}
			i++
		}
		if !found {
			if len(keys) >= MaxUniqueKeys {
				return &ValidationError{Err: ErrTooManyKeys, Field: "keys", Max: MaxUniqueKeys, Actual: len(keys) + 1}
			}
			return f.append(Record{Key: key, Value: value})
		}
		return nil
	})
}

// Load replaces the pool, preserving input order and duplicates. At most
// MaxUniqueKeys distinct keys are allowed. Invalid existing framing must first
// be repaired with Clear. Empty input creates or truncates the pool.
func (s *Store) Load(records []Record) error {
	if err := s.validateRecords(records); err != nil {
		return err
	}
	keys := make(map[string]struct{})
	for _, record := range records {
		keys[record.Key] = struct{}{}
	}
	if len(keys) > MaxUniqueKeys {
		return &ValidationError{Err: ErrTooManyKeys, Field: "keys", Max: MaxUniqueKeys, Actual: len(keys)}
	}
	return s.withFile(os.O_RDWR|os.O_CREATE, true, true, func(f *poolFile) error {
		if err := f.file.Truncate(0); err != nil {
			return err
		}
		f.count = 0
		for _, record := range records {
			if err := f.append(record); err != nil {
				return err
			}
		}
		return nil
	})
}

// Dump returns physical records in pool order, including duplicates.
// An absent pool is empty. Invalid framing or UTF-8 fails the entire read.
func (s *Store) Dump() ([]Record, error) {
	records := make([]Record, 0)
	err := s.scanRecords(func(record Record) {
		records = append(records, record)
	})
	if err != nil {
		return nil, err
	}
	return records, nil
}

// Entries returns the last value for each key.
func (s *Store) Entries() (map[string]string, error) {
	entries := make(map[string]string)
	err := s.scanRecords(func(record Record) {
		entries[record.Key] = record.Value
	})
	if err != nil {
		return nil, err
	}
	return entries, nil
}

// Read returns the last value and whether the key exists. It accepts keys
// beyond the store's write-size policy, but rejects empty keys and NUL.
func (s *Store) Read(key string) (string, bool, error) {
	if err := validateKey(key, -1); err != nil {
		return "", false, err
	}
	var value string
	found := false
	err := s.scanRecords(func(record Record) {
		if record.Key == key {
			value, found = record.Value, true
		}
	})
	if err != nil {
		return "", false, err
	}
	return value, found, nil
}

func (s *Store) scanRecords(visit func(Record)) error {
	return s.withFile(os.O_RDONLY, false, true, func(f *poolFile) error {
		for i := int64(0); i < f.count; i++ {
			record, err := f.read(i)
			if err != nil {
				return err
			}
			visit(record)
		}
		return nil
	})
}

func (s *Store) Delete(key string) (bool, error) {
	count, err := s.DeleteMultiple([]string{key})
	return count > 0, err
}

// DeleteMultiple removes all matching physical records, counting duplicates.
// Remaining records may be reordered. Empty input and missing files are no-ops.
func (s *Store) DeleteMultiple(keys []string) (int, error) {
	remove := make(map[string]bool, len(keys))
	for _, key := range keys {
		if err := validateKey(key, -1); err != nil {
			return 0, err
		}
		remove[key] = true
	}
	if len(remove) == 0 {
		return 0, nil
	}
	count := 0
	err := s.withFile(os.O_RDWR, true, true, func(f *poolFile) error {
		for i := int64(0); i < f.count; {
			record, err := f.read(i)
			if err != nil {
				return err
			}
			if remove[record.Key] {
				if err := f.remove(i); err != nil {
					return err
				}
				count++
			} else {
				i++
			}
		}
		return nil
	})
	return count, err
}

// Clear truncates even malformed files. A missing file remains absent.
func (s *Store) Clear() error {
	return s.withFile(os.O_RDWR, true, false, func(f *poolFile) error {
		return f.file.Truncate(0)
	})
}

// ClearIfStale checks and truncates under the same exclusive lock.
func (s *Store) ClearIfStale() error {
	return s.withFile(os.O_RDWR, true, false, func(f *poolFile) error {
		boot, err := s.ops.bootTime()
		if err != nil {
			return err
		}
		info, err := f.file.Stat()
		if err != nil {
			return err
		}
		if info.ModTime().Unix() <= boot {
			return f.file.Truncate(0)
		}
		return nil
	})
}

// IsStale compares whole-second modification time to Linux system boot.
// A missing pool is not stale.
func (s *Store) IsStale() (bool, error) {
	info, err := s.ops.stat(s.path)
	if os.IsNotExist(err) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	boot, err := s.ops.bootTime()
	if err != nil {
		return false, err
	}
	return info.ModTime().Unix() <= boot, nil
}

// Len returns the physical record count without decoding records.
func (s *Store) Len() (int64, error) {
	info, err := s.ops.stat(s.path)
	if os.IsNotExist(err) {
		return 0, nil
	}
	if err != nil {
		return 0, err
	}
	return recordCount(info.Size())
}

func (s *Store) IsEmpty() (bool, error) {
	count, err := s.Len()
	return count == 0, err
}

func (s *Store) validateRecords(records []Record) error {
	for _, record := range records {
		if err := validateKey(record.Key, s.MaxKeySize()); err != nil {
			return err
		}
		if strings.ContainsRune(record.Value, 0) {
			return ErrValueContainsNull
		}
		if !utf8.ValidString(record.Value) {
			return ErrInvalidUTF8
		}
		if len(record.Value) > s.MaxValueSize() {
			return &ValidationError{Err: ErrValueTooLarge, Field: "value", Max: s.MaxValueSize(), Actual: len(record.Value)}
		}
	}
	return nil
}

func validateKey(key string, max int) error {
	switch {
	case key == "":
		return ErrEmptyKey
	case strings.ContainsRune(key, 0):
		return ErrKeyContainsNull
	case !utf8.ValidString(key):
		return ErrInvalidUTF8
	case max >= 0 && len(key) > max:
		return &ValidationError{Err: ErrKeyTooLarge, Field: "key", Max: max, Actual: len(key)}
	}
	return nil
}

func (s *Store) withFile(flags int, exclusive, framing bool, fn func(*poolFile) error) (err error) {
	file, err := s.ops.open(s.path, flags)
	if os.IsNotExist(err) && flags&os.O_CREATE == 0 {
		return nil
	}
	if err != nil {
		return err
	}
	defer func() {
		err = errors.Join(err, file.Close())
	}()
	if err := file.lock(exclusive); err != nil {
		return fmt.Errorf("lock KVP pool %s: %w", s.path, err)
	}
	pool := &poolFile{file: file}
	if framing {
		info, err := file.Stat()
		if err != nil {
			return err
		}
		pool.count, err = recordCount(info.Size())
		if err != nil {
			return err
		}
	}
	return fn(pool)
}

type poolFile struct {
	file  poolHandle
	count int64
}

func (f *poolFile) read(index int64) (Record, error) {
	var data [RecordSize]byte
	if _, err := f.file.ReadAt(data[:], index*RecordSize); err != nil {
		return Record{}, err
	}
	decode := func(field []byte) (string, error) {
		if end := bytes.IndexByte(field, 0); end >= 0 {
			field = field[:end]
		}
		if !utf8.Valid(field) {
			return "", &os.PathError{Op: "decode", Path: f.file.Name(), Err: ErrInvalidUTF8}
		}
		return string(field), nil
	}
	key, err := decode(data[:WireMaxKeyBytes])
	if err != nil {
		return Record{}, err
	}
	value, err := decode(data[WireMaxKeyBytes:])
	return Record{Key: key, Value: value}, err
}

func (f *poolFile) append(record Record) error {
	var data [RecordSize]byte
	copy(data[:WireMaxKeyBytes], record.Key)
	copy(data[WireMaxKeyBytes:], record.Value)
	if err := writeAt(f.file, data[:], f.count*RecordSize); err != nil {
		return err
	}
	f.count++
	return nil
}

func (f *poolFile) remove(index int64) error {
	last := f.count - 1
	if index != last {
		var data [RecordSize]byte
		if _, err := f.file.ReadAt(data[:], last*RecordSize); err != nil {
			return err
		}
		if err := writeAt(f.file, data[:], index*RecordSize); err != nil {
			return err
		}
	}
	if err := f.file.Truncate(last * RecordSize); err != nil {
		return err
	}
	f.count--
	return nil
}

func recordCount(size int64) (int64, error) {
	if size < 0 || size%RecordSize != 0 {
		return 0, fmt.Errorf("%w: file size %d is not a multiple of %d", ErrInvalidFraming, size, RecordSize)
	}
	return size / RecordSize, nil
}

func bootTime() (int64, error) {
	return readBootTime("/proc/stat")
}

func readBootTime(path string) (int64, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	return parseBootTime(string(data))
}

func parseBootTime(contents string) (int64, error) {
	for _, line := range strings.Split(contents, "\n") {
		if strings.HasPrefix(line, "btime ") {
			value, err := strconv.ParseInt(strings.TrimSpace(line[len("btime "):]), 10, 64)
			if err != nil {
				return 0, fmt.Errorf("invalid /proc/stat btime: %w", err)
			}
			return value, nil
		}
	}
	return 0, fmt.Errorf("missing btime in /proc/stat")
}
